// Wave79 passed all four unchanged API53 result/error/state contracts.
func TestRunLeadPartialOptionContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLeadRemaining53.cls"), "@IsTest private class GladeLeadRemaining53 {\n private static Map<String,Object> counts(){return new Map<String,Object>{'accounts'=>[SELECT count() FROM Account],'contacts'=>[SELECT count() FROM Contact],'opportunities'=>[SELECT count() FROM Opportunity],'roles'=>[SELECT count() FROM OpportunityContactRole]};}\n private static Database.LeadConvert request(Id leadId,Id accountId,Id contactId,Id opportunityId,String status,Boolean idOption){\n  Database.LeadConvert value=new Database.LeadConvert();value.setLeadId(leadId);\n  value.setAccountId(accountId);value.setContactId(contactId);\n  value.setOwnerId(UserInfo.getUserId());value.setSendNotificationEmail(false);\n  value.setConvertedStatus(status);value.setDoNotCreateOpportunity(true);\n  if(idOption)value.setOpportunityId(opportunityId);else value.setOpportunityName('Test Opp');\n  return value;\n }\n private static Map<String,Object> resultRow(Database.LeadConvertResult value){\n  List<Object> errors=new List<Object>();\n  for(Database.Error error:value.getErrors())errors.add(new Map<String,Object>{'status'=>String.valueOf(error.getStatusCode()),'message'=>error.getMessage(),'fields'=>error.getFields()});\n  return new Map<String,Object>{'success'=>value.isSuccess(),'leadId'=>value.getLeadId(),'accountId'=>value.getAccountId(),'contactId'=>value.getContactId(),'opportunityId'=>value.getOpportunityId(),'errors'=>errors};\n }\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\n private static void exercise(Boolean idOption,Boolean defaultAllOrNone,Boolean listInput,String expectedJSON,String label){\n  Account account=new Account(Name='Owned conversion account');insert account;\n  Contact contact=new Contact(FirstName='Testy',LastName='Testy',AccountId=account.Id);insert contact;\n  Opportunity opportunity=new Opportunity(Name='Existing target',AccountId=account.Id,StageName='Prospecting',CloseDate=Date.newInstance(2026,1,1));insert opportunity;\n  List<Lead> leads=new List<Lead>{new Lead(FirstName='Testy',LastName='Testy',Company='Owned conversion account')};\n  if(listInput)leads.add(new Lead(FirstName='Testy',LastName='Second',Company='Owned conversion account'));\n  insert leads;\n  LeadStatus converted=[SELECT ApiName FROM LeadStatus WHERE IsConverted=true LIMIT 1];\n  List<Database.LeadConvert> requests=new List<Database.LeadConvert>();\n  for(Integer i=0;i<leads.size();i++)requests.add(request(leads[i].Id,account.Id,contact.Id,opportunity.Id,converted.ApiName,i==0?idOption:false));\n  Map<String,Object> observation=new Map<String,Object>{'idOption'=>idOption,'defaultAllOrNone'=>defaultAllOrNone,'listInput'=>listInput,'accountId'=>account.Id,'contactId'=>contact.Id,'opportunityId'=>opportunity.Id,'before'=>counts()};\n  List<Id> inputIds=new List<Id>();for(Lead lead:leads)inputIds.add(lead.Id);observation.put('inputLeadIds',inputIds);\n  Test.startTest();\n  try{\n   List<Object> results=new List<Object>();\n   if(listInput){for(Database.LeadConvertResult value:Database.convertLead(requests,false))results.add(resultRow(value));}\n   else if(defaultAllOrNone)results.add(resultRow(Database.convertLead(requests[0])));\n   else results.add(resultRow(Database.convertLead(requests[0],false)));\n   observation.put('results',results);\n  }catch(DmlException error){\n   List<Object> details=new List<Object>();\n   for(Integer i=0;i<error.getNumDml();i++)details.add(new Map<String,Object>{'index'=>error.getDmlIndex(i),'id'=>error.getDmlId(i),'status'=>String.valueOf(error.getDmlType(i)),'message'=>error.getDmlMessage(i),'fieldNames'=>error.getDmlFieldNames(i),'fieldTokens'=>error.getDmlFields(i)});\n   observation.put('exception',new Map<String,Object>{'type'=>error.getTypeName(),'message'=>error.getMessage(),'details'=>details});\n  }catch(Exception error){observation.put('exception',new Map<String,Object>{'type'=>error.getTypeName(),'message'=>error.getMessage()});}\n  observation.put('afterDml',counts());\n  Test.stopTest();\n  observation.put('afterStop',counts());\n  List<Object> stored=new List<Object>();\n  for(Lead lead:[SELECT Id,IsConverted,ConvertedAccountId,ConvertedContactId,ConvertedOpportunityId FROM Lead WHERE Id IN :inputIds ORDER BY Id])stored.add(new Map<String,Object>{'id'=>lead.Id,'converted'=>lead.IsConverted,'accountId'=>lead.ConvertedAccountId,'contactId'=>lead.ConvertedContactId,'opportunityId'=>lead.ConvertedOpportunityId});\n  observation.put('storedLeads',stored);observation.put('done',true);\n  String payload=JSON.serialize(observation);\n  System.assert(payload.length()<2900,'Complete remaining-option observation exceeds bound');\n  expectedJSON=expectedJSON.replace('$ACCOUNT',String.valueOf(account.Id)).replace('$CONTACT',String.valueOf(contact.Id)).replace('$OPPORTUNITY',String.valueOf(opportunity.Id));\n  List<Id> sortedInputIds=new List<Id>(inputIds);sortedInputIds.sort();\n  for(Integer i=0;i<inputIds.size();i++)expectedJSON=expectedJSON.replace('$LEAD'+i,String.valueOf(inputIds[i])).replace('$STORED'+i,String.valueOf(sortedInputIds[i]));\n  assertObserved(JSON.deserializeUntyped(expectedJSON),JSON.deserializeUntyped(payload),label);\n }\n @IsTest static void opportunityIdOnlyDefault(){exercise(true,true,false,'{\"done\":true,\"storedLeads\":[{\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"converted\":false,\"id\":\"$STORED0\"}],\"afterStop\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"afterDml\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"exception\":{\"details\":[{\"fieldTokens\":null,\"fieldNames\":[\"Id\"],\"message\":\"One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.\",\"status\":\"INVALID_FIELD\",\"id\":null,\"index\":0}],\"message\":\"ConvertLead failed. First exception on row 0; first error: INVALID_FIELD, One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.: [Id]\",\"type\":\"System.DmlException\"},\"inputLeadIds\":[\"$LEAD0\"],\"before\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"opportunityId\":\"$OPPORTUNITY\",\"contactId\":\"$CONTACT\",\"accountId\":\"$ACCOUNT\",\"listInput\":false,\"defaultAllOrNone\":true,\"idOption\":true}','opportunityIdOnlyDefault');}\n @IsTest static void opportunityIdOnlyPartial(){exercise(true,false,false,'{\"done\":true,\"storedLeads\":[{\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"converted\":false,\"id\":\"$STORED0\"}],\"afterStop\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"afterDml\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"results\":[{\"errors\":[{\"fields\":[\"Id\"],\"message\":\"One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.\",\"status\":\"INVALID_FIELD\"}],\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"leadId\":\"$LEAD0\",\"success\":false}],\"inputLeadIds\":[\"$LEAD0\"],\"before\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"opportunityId\":\"$OPPORTUNITY\",\"contactId\":\"$CONTACT\",\"accountId\":\"$ACCOUNT\",\"listInput\":false,\"defaultAllOrNone\":false,\"idOption\":true}','opportunityIdOnlyPartial');}\n @IsTest static void opportunityNamePartial(){exercise(false,false,false,'{\"done\":true,\"storedLeads\":[{\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"converted\":false,\"id\":\"$STORED0\"}],\"afterStop\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"afterDml\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"results\":[{\"errors\":[{\"fields\":[\"Id\"],\"message\":\"One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.\",\"status\":\"INVALID_FIELD\"}],\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"leadId\":\"$LEAD0\",\"success\":false}],\"inputLeadIds\":[\"$LEAD0\"],\"before\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"opportunityId\":\"$OPPORTUNITY\",\"contactId\":\"$CONTACT\",\"accountId\":\"$ACCOUNT\",\"listInput\":false,\"defaultAllOrNone\":false,\"idOption\":false}','opportunityNamePartial');}\n @IsTest static void listIdAndNamePartial(){exercise(true,false,true,'{\"done\":true,\"storedLeads\":[{\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"converted\":false,\"id\":\"$STORED0\"},{\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"converted\":false,\"id\":\"$STORED1\"}],\"afterStop\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"afterDml\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"results\":[{\"errors\":[{\"fields\":[\"Id\"],\"message\":\"One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.\",\"status\":\"INVALID_FIELD\"}],\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"leadId\":\"$LEAD0\",\"success\":false},{\"errors\":[{\"fields\":[\"Id\"],\"message\":\"One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.\",\"status\":\"INVALID_FIELD\"}],\"opportunityId\":null,\"contactId\":null,\"accountId\":null,\"leadId\":\"$LEAD1\",\"success\":false}],\"inputLeadIds\":[\"$LEAD0\",\"$LEAD1\"],\"before\":{\"roles\":0,\"opportunities\":1,\"contacts\":1,\"accounts\":1},\"opportunityId\":\"$OPPORTUNITY\",\"contactId\":\"$CONTACT\",\"accountId\":\"$ACCOUNT\",\"listInput\":true,\"defaultAllOrNone\":false,\"idOption\":true}','listIdAndNamePartial');}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLeadRemaining53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Skipped != 0 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("lead partial option contracts failed: %s", data)
	}
}
